import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Public vocabulary","description":"","frontmatter":{},"headers":[],"relativePath":"policies/public-vocabulary.md","filePath":"policies/public-vocabulary.md","lastUpdated":1793722866000}'),s={name:"policies/public-vocabulary.md"};function d(n,e,i,c,l,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="public-vocabulary" tabindex="-1">Public vocabulary <a class="header-anchor" href="#public-vocabulary" aria-label="Permalink to &quot;Public vocabulary&quot;">​</a></h1><p>The public website and the shell UI never name a protocol. The person is the point; the protocol is plumbing. This page is the denylist, the reasoning, and where the rule stops.</p><h2 id="the-rule" tabindex="-1">The rule <a class="header-anchor" href="#the-rule" aria-label="Permalink to &quot;The rule&quot;">​</a></h2><p><code>scripts/check-public-vocabulary.mjs</code> scans the built output of <code>apps/web</code> (the landing pages and the shell&#39;s UI copy) and fails the build on any of these, case-insensitively, as whole words or prefixes where marked:</p><table tabindex="0"><thead><tr><th>Denied</th><th>Say instead</th></tr></thead><tbody><tr><td><code>nostr</code></td><td>&quot;your account&quot;, &quot;the network&quot;</td></tr><tr><td><code>nip-</code> (prefix)</td><td>describe the behaviour: &quot;signing extension&quot;, &quot;remote signer&quot;, &quot;private messages&quot;</td></tr><tr><td><code>napplet</code></td><td>&quot;applet&quot;</td></tr><tr><td><code>relay</code></td><td>&quot;network&quot;, or nothing: the user&#39;s relays are &quot;where your account lives&quot;</td></tr><tr><td><code>pubkey</code></td><td>&quot;account&quot;, &quot;address&quot;</td></tr><tr><td><code>npub</code></td><td>&quot;address&quot;</td></tr><tr><td><code>nsec</code></td><td>&quot;secret key&quot;, in the one place the shell must warn about it</td></tr></tbody></table><p>Two checks enforce it:</p><ul><li><strong>Build time.</strong> <code>scripts/check-public-vocabulary.mjs</code> reads every HTML, Markdown, text, JSON and XML file in the Pages artifact outside <code>docs/</code>, so Astro pages, JSON-LD, <code>llms.txt</code> and the Markdown twins are covered.</li><li><strong>In a browser.</strong> <code>tests/e2e/public-vocabulary.spec.ts</code> loads every public page and walks the shell (sign-in, launcher, applet summary, a running applet&#39;s frame, the consent dialog with its record view open, and the guard, messages, grants and settings panels). It reads what a person can perceive: rendered text, <code>title</code>, <code>aria-label</code>, <code>placeholder</code> and <code>alt</code>. Copy rendered by scripts, which the file scan cannot see, is covered here.</li></ul><p>Identifiers inside JavaScript bundles are not copy and are not checked. The consent dialog&#39;s record view shows every field of the event it will sign, with plain labels (&quot;Signed by&quot;, &quot;Type&quot;, &quot;Labels&quot;) instead of wire field names.</p><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>Three reasons, in the order <code>SOUL.md</code> ranks them.</p><p><strong>The user&#39;s agency.</strong> A person deciding whether to run an applet needs to know what it will do and what it can reach. A protocol name tells them nothing about either; it tells them which club they are supposed to already belong to. &quot;This applet wants to publish on your behalf&quot; is a decision a person can make. &quot;This applet requires <code>relay</code> and <code>outbox</code>&quot; is not.</p><p><strong>Protocol conformance is a property of the code, not the copy.</strong> kernl conforms to NIP-5D and the NAPs, and the docs say so precisely. Saying so on the landing page would not make the code conform more; it would make the page about the specification instead of about what a person can do.</p><p><strong>Providers and bridges are chosen by what they do.</strong> A user chooses a messaging provider by whether their correspondent can read it and what an observer learns, not by its wire format. A bridge is &quot;downloads&quot;, not the name of a peer-to-peer protocol. Naming protocols in the UI would invite ranking by familiarity, which D-009 and D-010 rule out.</p><h2 id="where-the-rule-stops" tabindex="-1">Where the rule stops <a class="header-anchor" href="#where-the-rule-stops" aria-label="Permalink to &quot;Where the rule stops&quot;">​</a></h2><ul><li><strong>These docs.</strong> Written for developers, who need the names. Every page here uses them.</li><li><strong>Code, specs, commit messages, issues.</strong> <code>napplet</code> is the protocol term and stays in identifiers and in <code>features/</code>.</li><li><strong><code>specification</code> fields.</strong> <code>SecurityProperties.specification</code> and a bridge&#39;s protocol are shown in the docs, never in the picker.</li><li><strong>Addresses.</strong> Server URLs a user adds, edits or removes are data, and their hostnames belong to whoever runs the server. Both checks ignore <code>http(s)://</code> and <code>ws(s)://</code> URLs.</li><li><strong>The secret-key warning.</strong> The one place the shell mentions <code>nsec</code> is the warning that it will never ask for one.</li></ul><h2 id="the-words-we-use" tabindex="-1">The words we use <a class="header-anchor" href="#the-words-we-use" aria-label="Permalink to &quot;The words we use&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Say</th><th>Not</th><th>Why</th></tr></thead><tbody><tr><td>applet</td><td>napplet, app, dapp</td><td>&quot;napplet&quot; remains the protocol term in code and specs.</td></tr><tr><td>shell</td><td>OS, desktop, browser</td><td>kernl runs in a browser; it is not one.</td></tr><tr><td>grant</td><td>permission, capability</td><td>A grant is something the user gave and can take back.</td></tr><tr><td>provider</td><td>protocol</td><td>Users choose providers by what they do.</td></tr><tr><td>guard</td><td>firewall, mitigation</td><td>The guard is the set of protections between an applet and the user.</td></tr></tbody></table><p>Marketing adjectives, filler and hedges that hide a decision are out everywhere, including here.</p>',18)])])}const b=t(s,[["render",d]]);export{u as __pageData,b as default};
